Action: run_sql({'query': "WITH recent_inspections AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        i.inspection_date,\n        COUNT(CASE WHEN vc.critical THEN 1 END) AS critical_count\n    FROM inspections i\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2020-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, i.inspection_date\n),\nfirst_and_last AS (\n    SELECT \n        slchd_establishment_key,\n        FIRST(critical_count ORDER BY inspection_date ASC) as initial_critical,\n        LAST(critical_count ORDER BY inspection_date ASC) as recent_critical,\n        FIRST(inspection_date ORDER BY inspection_date ASC) as first_date,\n        LAST(inspection_date ORDER BY inspection_date ASC) as last_date,\n        COUNT(*) as total_inspections\n    FROM recent_inspections\n    GROUP BY slchd_establishment_key\n    HAVING COUNT(*) >= 2\n)\nSELECT \n    ek.name,\n    fl.slchd_establishment_key,\n    fl.first_date,\n    fl.initial_critical,\n    fl.last_date,\n    fl.recent_critical,\n    (fl.recent_critical - fl.initial_critical) as critical_change,\n    fl.total_inspections\nFROM first_and_last fl\nJOIN establishment_keys ek ON fl.slchd_establishment_key = ek.slchd_establishment_key\nORDER BY critical_change DESC\nLIMIT 20;"})

