Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.slchd_establishment_key,\n        i.inspection_id,\n        i.inspection_date,\n        COUNT(CASE WHEN vc.critical THEN 1 END) AS crit_count\n    FROM inspections i\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2020-01-01'\n    GROUP BY i.slchd_establishment_key, i.inspection_id, i.inspection_date\n),\nfirst_last AS (\n    SELECT \n        slchd_establishment_key,\n        FIRST(crit_count ORDER BY inspection_date ASC) as initial_crit,\n        LAST(crit_count ORDER BY inspection_date ASC) as recent_crit,\n        FIRST(inspection_date ORDER BY inspection_date ASC) as first_insp_date,\n        LAST(inspection_date ORDER BY inspection_date ASC) as last_insp_date,\n        COUNT(*) as total_inspections,\n        SUM(crit_count) as total_crit\n    FROM insp_crit\n    GROUP BY slchd_establishment_key\n    HAVING COUNT(*) >= 2\n)\nSELECT \n    ek.name,\n    fl.slchd_establishment_key,\n    fl.first_insp_date,\n    fl.initial_crit,\n    fl.last_insp_date,\n    fl.recent_crit,\n    (fl.recent_crit - fl.initial_crit) as crit_diff\nFROM first_last fl\nJOIN establishment_keys ek ON fl.slchd_establishment_key = ek.slchd_establishment_key\nORDER BY crit_diff DESC\nLIMIT 15;"})

